def _norm(groups):
    return sorted(sorted(g) for g in groups)

def test_basic():
    out = group_anagrams(["listen", "pots", "silent", "stop", "tops", "cat"])
    assert _norm(out) == _norm([["listen", "silent"], ["pots", "stop", "tops"], ["cat"]])

def test_empty_list():
    assert group_anagrams([]) == []

def test_empty_strings():
    assert _norm(group_anagrams(["", "", "a"])) == _norm([["", ""], ["a"]])

def test_no_anagrams():
    assert _norm(group_anagrams(["ab", "cd", "ef"])) == _norm([["ab"], ["cd"], ["ef"]])

def test_same_letters_different_counts():
    assert _norm(group_anagrams(["aab", "abb", "baa"])) == _norm([["aab", "baa"], ["abb"]])
